#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string number;
    int m;
    cin >> number >> m;

    const string keypad[] = {
        "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"
    };

    int letterToDigit[26];
    for (int digit = 2; digit <= 9; ++digit) {
        for (char c : keypad[digit]) {
            letterToDigit[c - 'a'] = digit;
        }
    }

    int count = 0;
    while (m--) {
        string word;
        cin >> word;

        if (word.size() != number.size()) continue;

        bool matches = true;
        for (size_t i = 0; i < word.size(); ++i) {
            if (letterToDigit[word[i] - 'a'] != number[i] - '0') {
                matches = false;
                break;
            }
        }
        if (matches) ++count;
    }

    cout << count << '\n';
    return 0;
}
